    delay(400);
    digitalWrite(DIR, LOW);
    delayMicroseconds(10);
    pulse(PUNI_KORACI * factor[i] / 20);
    Serial.print(F("MICRO 1/"));
    Serial.print(factor[i]);
    Serial.println(F(" 0 deg"));
